<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        mount </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;/run/secrets/database-password&quot;</span></span>
